'use strict';
// WebGL 1 particle renderer. One context, multiple scissored viewports.
// The spatial sampling and colours are generated by app.js from the original C++ model.
class AtomGPU {
  constructor(canvas) {
    this.canvas=canvas;
    const gl=canvas.getContext('webgl',{alpha:false,antialias:false,preserveDrawingBuffer:false,powerPreference:'high-performance'});
    if(!gl)throw new Error('WebGL unavailable');
    this.gl=gl;
    const vs=`attribute vec3 aPosition; attribute vec3 aColor;
      uniform vec2 uAngles; uniform float uCameraDistance; uniform float uAspect;
      uniform float uPointSize; uniform float uGamma; uniform float uGain; uniform float uCutaway;
      varying vec3 vColor;
      void main(){
        if(uCutaway>0.5 && aPosition.x<0.0 && aPosition.y>0.0){gl_Position=vec4(2.0,2.0,0.0,1.0);gl_PointSize=0.0;vColor=vec3(0.0);return;}
        float az=uAngles.x, el=uAngles.y;
        vec3 eye=uCameraDistance*vec3(cos(el)*cos(az),sin(el),cos(el)*sin(az));
        vec3 fw=normalize(-eye);
        vec3 right=normalize(cross(fw,vec3(0.0,1.0,0.0)));
        vec3 up=normalize(cross(right,fw));
        vec3 rel=aPosition-eye;
        float depth=max(0.0001,dot(rel,fw));
        float t=0.41421356237;
        float sx=dot(rel,right)/(depth*t*uAspect);
        float sy=dot(rel,up)/(depth*t);
        // Mimic the depth-tested, opaque spheres in the desktop OpenGL program.
        // Nearby samples must occlude distant samples, NOT add their RGB light.
        float linearDepth=clamp(depth/(2.0*uCameraDistance),0.0,1.0);
        gl_Position=vec4(sx,sy,2.0*linearDepth-1.0,1.0);
        gl_PointSize=uPointSize;
        vColor=min(vec3(1.0),pow(clamp(aColor,0.0,1.0),vec3(uGamma))*uGain);
      }`;
    const fs=`precision mediump float; varying vec3 vColor; uniform float uOpacity;
      void main(){
        vec2 p=gl_PointCoord*2.0-1.0;
        float rr=dot(p,p);
        if(rr>1.0) discard;
        // Crisp, antialiased sample markers rather than glowing point sprites.
        float coverage=1.0-smoothstep(0.89,1.0,rr);
        gl_FragColor=vec4(vColor,coverage*uOpacity);
      }`;
    const shader=(type,text)=>{const sh=gl.createShader(type);gl.shaderSource(sh,text);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh));return sh;};
    const program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vs));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fs));gl.linkProgram(program);
    if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(program));
    gl.useProgram(program);this.program=program;
    const uni=name=>gl.getUniformLocation(program,name);
    this.loc={angles:uni('uAngles'),distance:uni('uCameraDistance'),aspect:uni('uAspect'),size:uni('uPointSize'),gamma:uni('uGamma'),gain:uni('uGain'),opacity:uni('uOpacity'),cutaway:uni('uCutaway'),pos:gl.getAttribLocation(program,'aPosition'),color:gl.getAttribLocation(program,'aColor')};
    gl.enable(gl.SCISSOR_TEST);
    gl.enable(gl.BLEND);
    // Desktop uses SRC_ALPHA / ONE_MINUS_SRC_ALPHA and DEPTH_TEST.
    // Additive blending caused the neon-magenta saturation in v3.
    gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.depthMask(true);
    this.base=null;this.excited=null;this.previews=[];this.excitedPreviews=[];
    canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();this.ready=false;});
    this.ready=true;
  }
  createBuffer(points, preview=false){
    const gl=this.gl;
    // WebGL POINTS do not reproduce the depth coverage of the original
    // C++ shaded spheres. All 9000 preview samples therefore crowd into
    // an opaque purple blob. Preserve the 9000 samples for fitting/zoom,
    // but draw a stable, unbiased subset in the small preview slots.
    const maxVisible=preview?2300:points.length;
    const visibleCount=Math.min(points.length,maxVisible);
    const data=new Float32Array(visibleCount*6);
    for(let i=0;i<visibleCount;i++){
      const p=points[Math.floor((i+.5)*points.length/visibleCount)],j=i*6;
      data[j]=p.x;data[j+1]=p.y;data[j+2]=p.z;
      data[j+3]=p.c[0]/255;data[j+4]=p.c[1]/255;data[j+5]=p.c[2]/255;
    }
    const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,data,gl.STATIC_DRAW);
    return{buffer,count:visibleCount};
  }
  destroy(b){if(b)this.gl.deleteBuffer(b.buffer);}
  setGround(main,groups){this.destroy(this.base);this.previews.forEach(b=>this.destroy(b));this.previews=groups.map(g=>this.createBuffer(g,true));this.base=this.createBuffer(main);this.destroy(this.excited);this.excited=null;this.excitedPreviews.forEach(b=>this.destroy(b));this.excitedPreviews=[];}
  setExcited(points,previewGroups=[]){
    this.destroy(this.excited);this.excited=this.createBuffer(points);
    this.excitedPreviews.forEach(b=>this.destroy(b));
    this.excitedPreviews=previewGroups.map(g=>this.createBuffer(g,true));
  }
  rectangle(el){const root=this.canvas.getBoundingClientRect(),r=el.getBoundingClientRect();const kx=this.canvas.width/root.width,ky=this.canvas.height/root.height;
    return {x:Math.round((r.left-root.left)*kx),y:Math.round((root.bottom-r.bottom)*ky),w:Math.round(r.width*kx),h:Math.round(r.height*ky)};
  }
  prepareViewport(rect){const gl=this.gl,x=Math.max(0,rect.x),y=Math.max(0,rect.y),w=Math.max(1,rect.w),h=Math.max(1,rect.h);gl.viewport(x,y,w,h);gl.scissor(x,y,w,h);return{w,h};}
  draw(buffer,fraction,fit,rect,az,el,zoom,preview=false,opacity=1,cutaway=false){
    if(!buffer||fraction<=0)return;
    const gl=this.gl;
    const {w,h}=this.prepareViewport(rect);
    const aspect=w/h;
    const distance=Math.max(0.001,(fit/(Math.tan(Math.PI/8)*Math.min(1,aspect)))*(preview?1.12:1.1)/zoom);
    gl.uniform2f(this.loc.angles,az,el);
    gl.uniform1f(this.loc.distance,distance);
    gl.uniform1f(this.loc.aspect,aspect);
    const dpr=this.canvas.width/this.canvas.getBoundingClientRect().width;
    // Keep dots delicate as in the reference, especially in narrow preview slots.
    gl.uniform1f(this.loc.size,(preview?0.93:1.12)*Math.min(2,dpr));
    // C++ renderer: identical gamma and gain for main and preview samples.
    // Depth-tested, non-additive blending prevents the previous whiteout.
    gl.uniform1f(this.loc.gamma,preview?.60:.52);
    gl.uniform1f(this.loc.gain,preview?1.08:1.12);
    gl.uniform1f(this.loc.opacity,opacity);
    gl.uniform1f(this.loc.cutaway,cutaway?1:0);
    gl.bindBuffer(gl.ARRAY_BUFFER,buffer.buffer);
    gl.enableVertexAttribArray(this.loc.pos);
    gl.enableVertexAttribArray(this.loc.color);
    gl.vertexAttribPointer(this.loc.pos,3,gl.FLOAT,false,24,0);
    gl.vertexAttribPointer(this.loc.color,3,gl.FLOAT,false,24,12);
    gl.drawArrays(gl.POINTS,0,Math.floor(buffer.count*fraction));
  }
  render(display,state){
    if(!this.ready)return;
    const gl=this.gl,canvas=this.canvas;
    const root=canvas.getBoundingClientRect();
    const dpr=Math.min(1.7,window.devicePixelRatio||1);
    const w=Math.max(2,Math.round(root.width*dpr)),h=Math.max(2,Math.round(root.height*dpr));
    if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
    gl.viewport(0,0,w,h);gl.scissor(0,0,w,h);
    gl.clearColor(0,0,0,1);gl.clearDepth(1);
    gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
    const atom=document.getElementById('atomCanvas');const rect=this.rectangle(atom);
    const fit=display.to?display.fromFit*(1-display.t)+display.exc.excFit*display.t:display.fromFit;
    if(display.to){this.draw(this.base,1-display.t,fit,rect,state.azimuth,state.elevation,state.zoom,false,1,state.cutaway);this.draw(this.excited,display.t,fit,rect,state.azimuth,state.elevation,state.zoom,false,1,state.cutaway);}
    else this.draw(this.base,1,fit,rect,state.azimuth,state.elevation,state.zoom,false,1,state.cutaway);
    document.querySelectorAll('.slot').forEach(slot=>{
      const ground=Number(slot.dataset.ground),excited=Number(slot.dataset.excited);
      const rect=this.rectangle(slot);
      if(ground>=0 && this.previews[ground]){
        const fit=state.previewFit[ground]||1;
        this.draw(this.previews[ground],display.to?1-display.t:1,fit,rect,state.azimuth,state.elevation,1,true);
      }
      if(display.to&&excited>=0&&this.excitedPreviews[excited]){
        const fit=display.exc.previewFit[excited]||1;
        this.draw(this.excitedPreviews[excited],display.t,fit,rect,state.azimuth,state.elevation,1,true);
      }
    });
  }
}
window.AtomGPU=AtomGPU;
